// 6.2.1.2 (part 1) - checklist item set
// FLAG: this generic list is a PLACEHOLDER, same caveat already on record for Module 2.7's
// task template ('fixed regardless of service_type' - §10A.3 known limitation). No
// service-line-specific adoption checklist content exists in the uploads. Do not treat this
// as final client-facing copy without Nivy review.
const input = $('6.2.1 Trigger - Onboarding Complete').item.json;

const checklist = [
  'Kickoff call scheduled and completed',
  'Access/credentials handed over and confirmed working',
  'Primary point of contact identified on client side',
  'First deliverable/milestone reviewed with client',
  'Client has used/reviewed the Nextcloud shared folder at least once',
  'Reporting cadence and channel confirmed with client (per Module 2.8)'
];

return checklist.map(item_name => ({
  json: {
    client_id: input.client_id,
    odoo_project_id: input.odoo_project_id,
    odoo_lead_id: input.odoo_lead_id,
    service_type: input.service_type || null,
    task_name: item_name
  }
}));

